//! # Model catalog loading and updating module
//!
//! Reads `models.json` generated by the `@aio/models-data` package from bundled app resources,
//! and supports one-click fetching of the latest remote data saved to the AppData directory.
//!
//! ## Data priority
//! 1. **AppData cache** (`$APPDATA/com.loch.aio/models-catalog.json`, latest version pulled by the user)
//! 2. **Bundled resource** (`app.path().resource_dir()/models.json`, built-in app snapshot)
//! 3. **Dev fallback** (`node_modules/@aio/models-data/dist/data/models.json`)
//! 4. **Empty catalog** (last resort, frontend gets no error)
//!
//! ## Update mechanism
//! `update_models_catalog` fetches the latest JSON from a GitHub raw URL,
//! validates size/parsability, then writes it to the AppData directory. Takes effect after restart.

use serde::Serialize;
use std::fs;
use std::path::PathBuf;
use std::time::Duration;
use tauri::{Emitter, Manager};

use crate::ierr;

const DEFAULT_CATALOG_URL: &str =
    "https://raw.githubusercontent.com/Atom112/aio-models-data/main/dist/data/models.json";

/// Allowlist of hosts the catalog may be fetched from (SSRF protection)
const ALLOWED_CATALOG_HOSTS: &[&str] = &["raw.githubusercontent.com", "raw.githubusercontent.com."];

const APPDATA_FILENAME: &str = "models-catalog.json";
const BUNDLE_FILENAME: &str = "models.json";
const NODE_MODULES_REL: &str = "node_modules/@aio/models-data/dist/data/models.json";

/// Catalog body byte limit (10MB)
const MAX_CATALOG_BYTES: usize = 10 * 1024 * 1024;

const EMPTY_CATALOG: &str = r#"{
    "version": "0.0.0",
    "generatedAt": "1970-01-01T00:00:00.000Z",
    "source": "",
    "providerCount": 0,
    "modelCount": 0,
    "providers": [],
    "models": []
}"#;

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "snake_case")]
pub enum CatalogSource {
    Appdata,
    Bundled,
    DevFallback,
    Empty,
}

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct CatalogResponse {
    pub source: CatalogSource,
    pub json: String,
    pub path: Option<String>,
    pub version: Option<String>,
    pub generated_at: Option<String>,
}

#[derive(Serialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct UpdateResult {
    pub success: bool,
    pub model_count: usize,
    pub provider_count: usize,
    pub version: String,
    pub cached_path: String,
    pub error: Option<String>,
    pub bytes: usize,
    pub elapsed_ms: u128,
}

fn parse_catalog_meta(json: &str) -> (Option<String>, Option<String>, usize, usize) {
    let v: serde_json::Value = match serde_json::from_str(json) {
        Ok(v) => v,
        Err(_) => return (None, None, 0, 0),
    };
    let version = v.get("version").and_then(|x| x.as_str()).map(String::from);
    let generated_at = v
        .get("generatedAt")
        .and_then(|x| x.as_str())
        .map(String::from);
    let model_count = v.get("modelCount").and_then(|x| x.as_u64()).unwrap_or(0) as usize;
    let provider_count = v.get("providerCount").and_then(|x| x.as_u64()).unwrap_or(0) as usize;
    (version, generated_at, model_count, provider_count)
}

fn appdata_catalog_path(app: &tauri::AppHandle) -> Option<PathBuf> {
    let dir = app.path().app_data_dir().ok()?;
    if !dir.exists() {
        let _ = fs::create_dir_all(&dir);
    }
    Some(dir.join(APPDATA_FILENAME))
}

fn try_read(path: &PathBuf) -> Option<String> {
    if path.exists() {
        fs::read_to_string(path).ok()
    } else {
        None
    }
}

/// Load the currently effective catalog JSON (priority: AppData > Bundled > Dev > Empty)
#[tauri::command]
pub fn load_models_catalog(app: tauri::AppHandle) -> Result<String, String> {
    let resp = load_models_catalog_full(app)?;
    Ok(resp.json)
}

/// Load the currently effective catalog, with source metadata
#[tauri::command]
pub fn load_models_catalog_full(app: tauri::AppHandle) -> Result<CatalogResponse, String> {
    if let Some(p) = appdata_catalog_path(&app) {
        if let Some(content) = try_read(&p) {
            let (v, g, _, _) = parse_catalog_meta(&content);
            return Ok(CatalogResponse {
                source: CatalogSource::Appdata,
                json: content,
                path: Some(p.display().to_string()),
                version: v,
                generated_at: g,
            });
        }
    }

    if let Ok(resource_dir) = app.path().resource_dir() {
        let p = resource_dir.join(BUNDLE_FILENAME);
        if let Some(content) = try_read(&p) {
            let (v, g, _, _) = parse_catalog_meta(&content);
            return Ok(CatalogResponse {
                source: CatalogSource::Bundled,
                json: content,
                path: Some(p.display().to_string()),
                version: v,
                generated_at: g,
            });
        }
    }

    let manifest_dir = env!("CARGO_MANIFEST_DIR");
    for rel in &[
        "../".to_string() + NODE_MODULES_REL,
        NODE_MODULES_REL.to_string(),
    ] {
        let p = PathBuf::from(manifest_dir).join(rel);
        if let Some(content) = try_read(&p) {
            let (v, g, _, _) = parse_catalog_meta(&content);
            return Ok(CatalogResponse {
                source: CatalogSource::DevFallback,
                json: content,
                path: Some(p.display().to_string()),
                version: v,
                generated_at: g,
            });
        }
    }

    Ok(CatalogResponse {
        source: CatalogSource::Empty,
        json: EMPTY_CATALOG.to_string(),
        path: None,
        version: None,
        generated_at: None,
    })
}

/// Validate that the URL points to an allowlisted host (SSRF protection)
fn validate_catalog_url(target: &str) -> Result<(), String> {
    // Unified SSRF protection (HTTPS-only + IP/private-network rejection)
    crate::utils::url_validation::validate_http_url(
        target,
        &crate::utils::url_validation::HttpUrlOptions::https_only(),
    )?;
    // Additional host allowlist (only raw.githubusercontent.com is permitted)
    let parsed = url::Url::parse(target)
        .map_err(|e| ierr!("URL 解析失败: {}", "Failed to parse URL: {}", e))?;
    let host = parsed.host_str().unwrap_or("").to_lowercase();
    if !ALLOWED_CATALOG_HOSTS.iter().any(|h| host == *h) {
        return Err(ierr!(
            "catalog host 未在白名单内: {}",
            "Catalog host is not in the allowlist: {}",
            host
        ));
    }
    Ok(())
}

/// Fetch the latest catalog and save it to AppData
#[tauri::command]
pub async fn update_models_catalog(
    app: tauri::AppHandle,
    url: Option<String>,
) -> Result<UpdateResult, String> {
    let target_url = url.unwrap_or_else(|| DEFAULT_CATALOG_URL.to_string());
    // SSRF protection: validate the URL first
    if let Err(e) = validate_catalog_url(&target_url) {
        return Ok(UpdateResult {
            success: false,
            model_count: 0,
            provider_count: 0,
            version: String::new(),
            cached_path: String::new(),
            error: Some(e),
            bytes: 0,
            elapsed_ms: 0,
        });
    }
    let started = std::time::Instant::now();

    let client = reqwest::Client::builder()
        .user_agent(format!(
            "AIO-Desktop/{} (aio-models-data-updater)",
            env!("CARGO_PKG_VERSION")
        ))
        .timeout(Duration::from_secs(30))
        .connect_timeout(Duration::from_secs(5))
        .build()
        .map_err(|e| {
            ierr!(
                "构造 HTTP 客户端失败: {}",
                "Failed to build HTTP client: {}",
                e
            )
        })?;

    let resp = client
        .get(&target_url)
        .send()
        .await
        .map_err(|e| ierr!("拉取失败: {}", "Fetch failed: {}", e))?;

    if !resp.status().is_success() {
        return Ok(UpdateResult {
            success: false,
            model_count: 0,
            provider_count: 0,
            version: String::new(),
            cached_path: String::new(),
            error: Some(format!(
                "HTTP {} {}",
                resp.status().as_u16(),
                resp.status().canonical_reason().unwrap_or("")
            )),
            bytes: 0,
            elapsed_ms: started.elapsed().as_millis(),
        });
    }

    // Cap the body size to prevent OOM
    let body = resp
        .bytes()
        .await
        .map_err(|e| ierr!("读取响应体失败: {}", "Failed to read response body: {}", e))?;
    if body.len() > MAX_CATALOG_BYTES {
        return Ok(UpdateResult {
            success: false,
            model_count: 0,
            provider_count: 0,
            version: String::new(),
            cached_path: String::new(),
            error: Some(ierr!(
                "响应体超过 {}MB 上限",
                "Response body exceeds the {}MB limit",
                MAX_CATALOG_BYTES / 1024 / 1024
            )),
            bytes: body.len(),
            elapsed_ms: started.elapsed().as_millis(),
        });
    }
    let body_str = String::from_utf8_lossy(&body).into_owned();

    if body_str.len() < 1024 {
        return Ok(UpdateResult {
            success: false,
            model_count: 0,
            provider_count: 0,
            version: String::new(),
            cached_path: String::new(),
            error: Some(ierr!(
                "响应体过小 ({} 字节)，可能不是有效 catalog",
                "Response body too small ({} bytes), may not be a valid catalog",
                body_str.len()
            )),
            bytes: body_str.len(),
            elapsed_ms: started.elapsed().as_millis(),
        });
    }

    let (version, _generated_at, model_count, provider_count) = parse_catalog_meta(&body_str);
    if model_count == 0 {
        return Ok(UpdateResult {
            success: false,
            model_count: 0,
            provider_count: 0,
            version: version.clone().unwrap_or_default(),
            cached_path: String::new(),
            error: Some(ierr!(
                "响应体不包含 modelCount 字段，可能不是 catalog JSON",
                "Response body has no modelCount field, may not be a catalog JSON"
            )),
            bytes: body_str.len(),
            elapsed_ms: started.elapsed().as_millis(),
        });
    }

    let cached = appdata_catalog_path(&app)
        .ok_or_else(|| ierr!("无法获取 AppData 目录", "Failed to get AppData directory"))?;

    fs::write(&cached, &body).map_err(|e| {
        ierr!(
            "写入 AppData 失败 ({}): {}",
            "Failed to write to AppData ({}): {}",
            cached.display(),
            e
        )
    })?;

    let _ = app.emit(
        "models-catalog-updated",
        serde_json::json!({
            "version": version,
            "modelCount": model_count,
            "providerCount": provider_count,
            "path": cached.display().to_string(),
        }),
    );

    Ok(UpdateResult {
        success: true,
        model_count,
        provider_count,
        version: version.unwrap_or_else(|| "unknown".to_string()),
        cached_path: cached.display().to_string(),
        error: None,
        bytes: body_str.len(),
        elapsed_ms: started.elapsed().as_millis(),
    })
}

/// Get the current catalog URL configuration (for UI display)
#[tauri::command]
pub fn get_catalog_url() -> String {
    DEFAULT_CATALOG_URL.to_string()
}
